CardSets.register({"id":"theme-parks","name":"Theme Parks & Attractions","code":"PARK","description":"420 cards of gates, castles and dark rides — the world's great theme parks, beloved attractions, lost parks and rides, park icons, themed lands, nighttime spectaculars and water parks.","theme":{"primary":"#146b8a","secondary":"#e07b2c","artBackground":"#eef6f3","artFit":"cover"},"pack":{"name":"Theme Parks Pack","emblem":"🎡","skin":"theme-parks"},"cards":[{"name":"Cedar Point","rarity":"chase","id":"cedar-point","subtitle":"Parks","details":"Opened in 1870 on a Lake Erie peninsula in Sandusky, Ohio, and famed for its dense coaster skyline, classic midway and beachfront setting.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Cedar_Point_skyline_with_coasters_seen_from_parking_lot%2C_GateKeeper%2C_May_2018_-_ThrillZing.jpg/1280px-Cedar_Point_skyline_with_coasters_seen_from_parking_lot%2C_GateKeeper%2C_May_2018_-_ThrillZing.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Magic Kingdom","rarity":"chase","id":"magic-kingdom","subtitle":"Parks","details":"Opened in 1971 at Walt Disney World in Florida, built around Cinderella Castle and six themed lands radiating from a central hub.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c0/Main_Street_Magic_Kingdom_Walt_Disney_World_%282452690822%29.jpg/1280px-Main_Street_Magic_Kingdom_Walt_Disney_World_%282452690822%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Tokyo DisneySea","rarity":"chase","id":"tokyo-disneysea","subtitle":"Parks","details":"Opened in 2001 in Urayasu, Japan, a one-of-a-kind nautical Disney park whose ports of call circle a harbor and Mount Prometheus volcano.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Tokyo_DisneySea_Arabian_Coast_View1_20130607.jpg/1280px-Tokyo_DisneySea_Arabian_Coast_View1_20130607.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Europa-Park","rarity":"chase","id":"europa-park","subtitle":"Parks","details":"Opened in 1975 in Rust, Germany, by the Mack family, with areas themed to European countries and a reputation for detailed, lush landscaping.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Europa_Park_Entrance_2016.jpg/1280px-Europa_Park_Entrance_2016.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Universal Islands of Adventure","rarity":"chase","id":"universal-islands-of-adventure","subtitle":"Parks","details":"Opened in 1999 in Orlando, Florida, arranging boldly themed islands around a lagoon, each entered through its own distinctive portal.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/IOALighthouse.JPG/1280px-IOALighthouse.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Efteling","rarity":"chase","id":"efteling","subtitle":"Parks","details":"Opened in 1952 in Kaatsheuvel, Netherlands, growing from a Fairytale Forest of storybook scenes into a park rooted in folklore and nature.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Efteling_The_House_of_the_Five_Senses.jpg/1280px-Efteling_The_House_of_the_Five_Senses.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Disneyland Park (California)","rarity":"chase","id":"disneyland-park-california","subtitle":"Parks","details":"Opened in 1955 in Anaheim, California, the only Disney park built under Walt Disney's direct supervision, anchored by Sleeping Beauty Castle.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Sleeping_Beauty_Castle_Disneyland_Anaheim_2013.jpg/1280px-Sleeping_Beauty_Castle_Disneyland_Anaheim_2013.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Blackpool Pleasure Beach","rarity":"chase","id":"blackpool-pleasure-beach","subtitle":"Parks","details":"Founded in 1896 on Blackpool's seafront in England, a family-run park packing historic wooden coasters and modern rides into a compact site.","image":"https://upload.wikimedia.org/wikipedia/commons/8/87/The_Big_One%2C_Blackpool_pleasure_beach_-_geograph.org.uk_-_383991.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Knoebels","rarity":"chase","id":"knoebels","subtitle":"Parks","details":"Opened in 1926 in Elysburg, Pennsylvania, a free-admission park in a wooded valley known for classic rides, campgrounds and hearty park food.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Knoebels_Phoenix.JPG/1280px-Knoebels_Phoenix.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Silver Dollar City","rarity":"chase","id":"silver-dollar-city","subtitle":"Parks","details":"Opened in 1960 above Marvel Cave in Branson, Missouri, an 1880s Ozarks craft village with demonstrating artisans, festivals and cave tours.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Frisco_Silver_Dollar_Line_Locomotive_No._13_at_the_station%2C_May_2015.jpg/1280px-Frisco_Silver_Dollar_Line_Locomotive_No._13_at_the_station%2C_May_2015.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Epcot","rarity":"legendary","id":"epcot","subtitle":"Parks","details":"Opened in 1982 at Walt Disney World, split between a celebration of technology and innovation and a World Showcase of national pavilions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Spaceship_Earth_and_entry_plaza_2021.jpg/1280px-Spaceship_Earth_and_entry_plaza_2021.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Disney's Animal Kingdom","rarity":"legendary","id":"disneys-animal-kingdom","subtitle":"Parks","details":"Opened in 1998 at Walt Disney World, blending live animal habitats with themed lands, its centerpiece the sculpted Tree of Life.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Tree_of_Life%2C_Disney%27s_Animal_Kingdom.jpg/1280px-Tree_of_Life%2C_Disney%27s_Animal_Kingdom.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Universal Studios Florida","rarity":"legendary","id":"universal-studios-florida","subtitle":"Parks","details":"Opened in 1990 in Orlando, the original Universal park on the East Coast, built as a working studio-style lot of movie-inspired areas.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e3/Universal_Orlando_Gateway_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Universal Studios Japan","rarity":"legendary","id":"universal-studios-japan","subtitle":"Parks","details":"Opened in 2001 in Osaka, the first Universal park in Asia, drawing huge crowds to its mix of Hollywood and Japanese pop-culture areas.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/UNIVERSAL_STUDIOS_JAPAN_ENTRANCE.jpg/1280px-UNIVERSAL_STUDIOS_JAPAN_ENTRANCE.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Tokyo Disneyland","rarity":"legendary","id":"tokyo-disneyland","subtitle":"Parks","details":"Opened in 1983 in Urayasu, the first Disney park outside the United States, modeled on the classic California and Florida castle parks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Tokyo_Disneyland_Cinderella_Castle_2023-07-02.jpg/1280px-Tokyo_Disneyland_Cinderella_Castle_2023-07-02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Shanghai Disneyland","rarity":"legendary","id":"shanghai-disneyland","subtitle":"Parks","details":"Opened in 2016 in Pudong, China, reimagining the castle park with the tallest Disney castle and lands designed for Chinese audiences.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Enchanted_Storybook_Castle.jpg/1280px-Enchanted_Storybook_Castle.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Hong Kong Disneyland","rarity":"legendary","id":"hong-kong-disneyland","subtitle":"Parks","details":"Opened in 2005 on Lantau Island, a castle park set against green mountains, expanded with lands found at no other Disney resort.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/Sleeping_Beauty_Castle_at_Hong_Kong_Disneyland_200705.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Disneyland Park (Paris)","rarity":"legendary","id":"disneyland-park-paris","subtitle":"Parks","details":"Opened in 1992 in Marne-la-Vallee, France, a castle park praised for its detailed landscaping, arcades and storybook European styling.","image":"https://thumb.wikimedia.org/wikipedia/en/thumb/8/88/Sleeping_Beauty_Castle%2C_Disneyland%2C_Paris.jpg/1280px-Sleeping_Beauty_Castle%2C_Disneyland%2C_Paris.jpg"},{"name":"Alton Towers","rarity":"legendary","id":"alton-towers","subtitle":"Parks","details":"A Staffordshire estate in England whose gardens opened to the public in 1860, growing into a park of rides hidden among wooded valleys.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6b/Alton_Towers_-_geograph.org.uk_-_1464460.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"PortAventura Park","rarity":"legendary","id":"portaventura-park","subtitle":"Parks","details":"Opened in 1995 in Salou, Spain, a resort park of world regions from the Mediterranean to Polynesia, beside the Mediterranean coast.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/PortAventura_parque_de_atracciones.jpg/1280px-PortAventura_parque_de_atracciones.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Phantasialand","rarity":"legendary","id":"phantasialand","subtitle":"Parks","details":"Opened in 1967 in Bruhl, Germany, a compact park famed for densely themed immersive areas packed into a remarkably small footprint.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Phantasialand_Br%C3%BChl14.jpg/1280px-Phantasialand_Br%C3%BChl14.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Tivoli Gardens","rarity":"legendary","id":"tivoli-gardens","subtitle":"Parks","details":"Opened in 1843 in central Copenhagen, Denmark, a pleasure garden of pavilions, lakes and rides that helped inspire Walt Disney's Disneyland.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Copenhagen_visit_July_1996_-_Tivoli_Gardens_exterior.jpg/1280px-Copenhagen_visit_July_1996_-_Tivoli_Gardens_exterior.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Disney California Adventure","rarity":"epic","id":"disney-california-adventure","subtitle":"Parks","details":"Opened in 2001 in Anaheim, California, across from Disneyland, celebrating California landscapes and stories around Grizzly Peak.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Disney_California_Adventure_Park_entrance_%28Buena_Vista_Street%29.jpg/1280px-Disney_California_Adventure_Park_entrance_%28Buena_Vista_Street%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Disney's Hollywood Studios","rarity":"epic","id":"disneys-hollywood-studios","subtitle":"Parks","details":"Opened in 1989 at Walt Disney World as a working-studio park, later reshaped around immersive lands drawn from film franchises.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Hollywood_Tower_Hotel.jpg/1280px-Hollywood_Tower_Hotel.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Universal Studios Hollywood","rarity":"epic","id":"universal-studios-hollywood","subtitle":"Parks","details":"Opened in 1964 in Los Angeles, California, pairing a real film-studio tram tour with rides on a hillside lot above the San Fernando Valley.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Universal_Studios_Hollywood_Entrance_%282570304287%29.jpg/1280px-Universal_Studios_Hollywood_Entrance_%282570304287%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Universal Epic Universe","rarity":"epic","id":"universal-epic-universe","subtitle":"Parks","details":"Opened in 2025 in Orlando, Florida, Universal's portal-style park of distinct worlds reached through gardens and Celestial Park.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Chronos_Tower_Front_Epic_Universe.jpg/1280px-Chronos_Tower_Front_Epic_Universe.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Hersheypark","rarity":"epic","id":"hersheypark","subtitle":"Parks","details":"Opened in 1907 in Hershey, Pennsylvania, founded for Hershey chocolate workers, mixing coasters with the adjacent Chocolate World and ZooAmerica.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Hersheypark_Entrance_10-2-2022.jpg/1280px-Hersheypark_Entrance_10-2-2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Dollywood","rarity":"epic","id":"dollywood","subtitle":"Parks","details":"Opened in 1986 in Pigeon Forge, Tennessee, Dolly Parton's Smoky Mountain park of crafts, gospel and country music, and mountain coasters.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Buildings_at_Dollywood_in_Pigeon_Forge%2C_Tennessee.jpg/1280px-Buildings_at_Dollywood_in_Pigeon_Forge%2C_Tennessee.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Busch Gardens Tampa Bay","rarity":"epic","id":"busch-gardens-tampa-bay","subtitle":"Parks","details":"Opened in 1959 in Tampa, Florida, pairing African animal habitats and a Serengeti plain with one of America's densest coaster lineups.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Busch_Gardens%2C_April_11%2C_2001.jpg/1280px-Busch_Gardens%2C_April_11%2C_2001.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Busch Gardens Williamsburg","rarity":"epic","id":"busch-gardens-williamsburg","subtitle":"Parks","details":"Opened in 1975 in Williamsburg, Virginia, a park of European hamlets set in rolling, heavily wooded terrain along the James River.","image":"https://upload.wikimedia.org/wikipedia/commons/6/66/Busch_Gardens_-_%22Rhine_River%22.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"SeaWorld Orlando","rarity":"epic","id":"seaworld-orlando","subtitle":"Parks","details":"Opened in 1973 in Orlando, Florida, combining marine animal exhibits, shows and rescue work with major thrill coasters.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Manta%27s_loop_above_the_rooftops_of_the_entrance_plaza_with_a_lighthouse_under_scaffolding_at_left_at_SeaWorld_Orlando%2C_March_2021_-_ThrillZing.jpg/1280px-Manta%27s_loop_above_the_rooftops_of_the_entrance_plaza_with_a_lighthouse_under_scaffolding_at_left_at_SeaWorld_Orlando%2C_March_2021_-_ThrillZing.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kings Island","rarity":"epic","id":"kings-island","subtitle":"Parks","details":"Opened in 1972 near Cincinnati, Ohio, a park anchored by International Street and a one-third-scale replica of the Eiffel Tower.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Kings_Island_-_20260713-153621.jpg/1280px-Kings_Island_-_20260713-153621.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Knott's Berry Farm","rarity":"epic","id":"knotts-berry-farm","subtitle":"Parks","details":"Grew from a 1920s Buena Park, California berry stand into a park whose Ghost Town preserves buildings moved from real Western mining towns.","image":"https://upload.wikimedia.org/wikipedia/commons/d/da/Knotts_Gate_twilight.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Liseberg","rarity":"epic","id":"liseberg","subtitle":"Parks","details":"Opened in 1923 in Gothenburg, Sweden, a beloved city park of gardens, concert stages and Scandinavian wooden coaster tradition.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d5/Lisebergsentr%C3%A9n.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Parc Astérix","rarity":"epic","id":"parc-asterix","subtitle":"Parks","details":"Opened in 1989 near Paris, France, a park built on the Asterix comics, mixing Gallic humor with major coasters and water rides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/The_entrance_to_La_Descente_du_Nil.jpg/1280px-The_entrance_to_La_Descente_du_Nil.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Puy du Fou","rarity":"epic","id":"puy-du-fou","subtitle":"Parks","details":"Opened in 1989 in western France, a park of large-scale historical spectacle shows and recreated villages, with almost no traditional rides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Puy-du-Fou-4.JPG/1280px-Puy-du-Fou-4.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Gardaland","rarity":"epic","id":"gardaland","subtitle":"Parks","details":"Opened in 1975 on the shore of Lake Garda in Italy, the country's flagship park, with themed areas beside one of Europe's great lakes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Castelnuovo_del_Garda_-_Gardaland_-_202109120805.jpg/1280px-Castelnuovo_del_Garda_-_Gardaland_-_202109120805.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Everland","rarity":"epic","id":"everland","subtitle":"Parks","details":"Opened in 1976 in Yongin, South Korea, a sprawling hillside resort park with a zoo, gardens and seasonal flower festivals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/Entrance_of_Everland.jpg/1280px-Entrance_of_Everland.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Lotte World","rarity":"epic","id":"lotte-world","subtitle":"Parks","details":"Opened in 1989 in Seoul, South Korea, pairing a vast indoor park under a glass dome with an outdoor island on Seokchon Lake.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Lotte_World_morning_view_8.jpg/1280px-Lotte_World_morning_view_8.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Chimelong Paradise","rarity":"epic","id":"chimelong-paradise","subtitle":"Parks","details":"Opened in 2006 in Guangzhou, China, the flagship ride park of the Chimelong resort, known for record-chasing coasters and big live shows.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Chimelong_Paradise_152.jpg/1280px-Chimelong_Paradise_152.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Walt Disney Studios Park","rarity":"rare","id":"walt-disney-studios-park","subtitle":"Parks","details":"Opened in 2002 beside Disneyland Paris, a studio-themed park built around production courtyards, stunt shows and animation.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Entrance_gate_of_Walt_Disney_Studios_Park%2C_Disneyland_Paris.jpg/1280px-Entrance_gate_of_Walt_Disney_Studios_Park%2C_Disneyland_Paris.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Universal Studios Singapore","rarity":"rare","id":"universal-studios-singapore","subtitle":"Parks","details":"Opened in 2010 on Sentosa Island, a compact Universal park of seven zones squeezed onto a resort island off Singapore's coast.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Universal_Studios_Singapore_globe_%28125026%29.jpg/1280px-Universal_Studios_Singapore_globe_%28125026%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Universal Studios Beijing","rarity":"rare","id":"universal-studios-beijing","subtitle":"Parks","details":"Opened in 2021, Universal's park in China, with lands blending Hollywood franchises and a Kung Fu Panda area under a giant dome.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3d/Universal_Studios_Beijing_globe_square_%2820210907121340%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"SeaWorld San Diego","rarity":"rare","id":"seaworld-san-diego","subtitle":"Parks","details":"Opened in 1964 in Mission Bay, San Diego, the original SeaWorld, combining oceanariums, animal encounters and coastal coasters.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/MantaEntranceSanDiego.jpg/1280px-MantaEntranceSanDiego.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"SeaWorld San Antonio","rarity":"rare","id":"seaworld-san-antonio","subtitle":"Parks","details":"Opened in 1988 in San Antonio, Texas, the largest SeaWorld park by acreage, mixing marine exhibits with water rides and coasters.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Entrance_to_Sea_World%2C_San_Antonio%2C_Texas%2C_June_4%2C_2007.JPG/1280px-Entrance_to_Sea_World%2C_San_Antonio%2C_Texas%2C_June_4%2C_2007.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Six Flags Magic Mountain","rarity":"rare","id":"six-flags-magic-mountain","subtitle":"Parks","details":"Opened in 1971 in Valencia, California, a mountain park long marketed on its enormous coaster count under the California sun.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Six_Flags_Magic_Mountain_Entrance_Plaza_April_2026.jpg/1280px-Six_Flags_Magic_Mountain_Entrance_Plaza_April_2026.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Six Flags Great Adventure","rarity":"rare","id":"six-flags-great-adventure","subtitle":"Parks","details":"Opened in 1974 in Jackson, New Jersey, a park paired with a drive-through safari that became one of its signature experiences.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Six_Flags_Great_Adventure_entrance_gate_1.jpg/1280px-Six_Flags_Great_Adventure_entrance_gate_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Six Flags Great America","rarity":"rare","id":"six-flags-great-america","subtitle":"Parks","details":"Opened in 1976 in Gurnee, Illinois, a Marriott-built park of American-themed areas between Chicago and Milwaukee.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Columbia_Carousel_Six_Flags_Great_America_2025.jpg/1280px-Columbia_Carousel_Six_Flags_Great_America_2025.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Canada's Wonderland","rarity":"rare","id":"canadas-wonderland","subtitle":"Parks","details":"Opened in 1981 north of Toronto, Canada's flagship park, fronted by Wonder Mountain and its waterfall above International Street.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Canada%27s_Wonderland_%287412109622%29.jpg/1280px-Canada%27s_Wonderland_%287412109622%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kings Dominion","rarity":"rare","id":"kings-dominion","subtitle":"Parks","details":"Opened in 1975 near Richmond, Virginia, sister park to Kings Island, with its own Eiffel Tower replica and shaded midways.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cb/Kings_Dominion_Eiffel_Tower.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Carowinds","rarity":"rare","id":"carowinds","subtitle":"Parks","details":"Opened in 1973 straddling the North and South Carolina state line near Charlotte, letting guests cross between states mid-park.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Carowinds_aerial_view%2C_September_2017.JPG/1280px-Carowinds_aerial_view%2C_September_2017.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Holiday World","rarity":"rare","id":"holiday-world","subtitle":"Parks","details":"Opened in 1946 in Santa Claus, Indiana, a family-owned park themed to holidays, famed for free soft drinks and wooden coasters.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Holiday_World_Entrance_Gates_-_Jeremy_Thompson.jpg/1280px-Holiday_World_Entrance_Gates_-_Jeremy_Thompson.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kennywood","rarity":"rare","id":"kennywood","subtitle":"Parks","details":"Opened in 1898 as a trolley park near Pittsburgh, Pennsylvania, a National Historic Landmark preserving century-old rides and pavilions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Lost_Kennywood.jpg/1280px-Lost_Kennywood.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Fuji-Q Highland","rarity":"rare","id":"fuji-q-highland","subtitle":"Parks","details":"Opened in 1968 at the foot of Mount Fuji in Japan, a park famous for extreme, record-setting coasters beneath the mountain's gaze.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/View_of_Mount_Fuji_from_the_Ferris_wheel_at_Fuji-Q_Highland_-_Aug_30%2C_2011.jpg/1280px-View_of_Mount_Fuji_from_the_Ferris_wheel_at_Fuji-Q_Highland_-_Aug_30%2C_2011.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Nagashima Spa Land","rarity":"rare","id":"nagashima-spa-land","subtitle":"Parks","details":"Opened in 1966 in Kuwana, Japan, part of a hot-spring resort complex, with a huge coaster lineup beside Nabana no Sato gardens.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Nagashima_spa_land_skyview.jpg/1280px-Nagashima_spa_land_skyview.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Gröna Lund","rarity":"rare","id":"grona-lund","subtitle":"Parks","details":"Opened in 1883 on Stockholm's Djurgarden island in Sweden, a waterfront park squeezing rides and concert stages into a tight shoreline.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Gr%C3%B6na_Lund_June_2015.jpg/1280px-Gr%C3%B6na_Lund_June_2015.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Futuroscope","rarity":"rare","id":"futuroscope","subtitle":"Parks","details":"Opened in 1987 near Poitiers, France, a park built around giant cinema screens, 3D films and multimedia attractions in futuristic pavilions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Le_parc_du_futuroscope.JPG/1280px-Le_parc_du_futuroscope.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Mirabilandia","rarity":"rare","id":"mirabilandia","subtitle":"Parks","details":"Opened in 1992 near Ravenna, Italy, one of the country's largest parks, set among pine woods a short drive from the Adriatic coast.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Mirab-img0004.JPG/1280px-Mirab-img0004.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Heide Park","rarity":"rare","id":"heide-park","subtitle":"Parks","details":"Opened in 1978 in Soltau, Germany, a large park built in a former wildlife preserve, mixing big coasters with landscaped gardens.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Heide-Park_entrance_%28Soltau_-_Germany%29.jpg/1280px-Heide-Park_entrance_%28Soltau_-_Germany%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Hansa-Park","rarity":"rare","id":"hansa-park","subtitle":"Parks","details":"Opened in 1977 at Sierksdorf on Germany's Baltic coast, a Hanseatic League-themed park where rides sit among recreated trading-city facades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Hansa-Park_Eingangsbereich_2010.JPG/1280px-Hansa-Park_Eingangsbereich_2010.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Movie Park Germany","rarity":"rare","id":"movie-park-germany","subtitle":"Parks","details":"Opened in 1996 in Bottrop, Germany, a film-studio park of movie streets, stunt shows and sets on the site of earlier leisure parks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Entrance_Movie_Park.JPG/1280px-Entrance_Movie_Park.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ocean Park Hong Kong","rarity":"rare","id":"ocean-park-hong-kong","subtitle":"Parks","details":"Opened in 1977 on Hong Kong Island, an oceanarium and ride park split across a headland, linked by cable cars over the sea.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Ocean_Park_cable_car_system_%28Hong_Kong%29.jpg/1280px-Ocean_Park_cable_car_system_%28Hong_Kong%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Warner Bros. World Abu Dhabi","rarity":"rare","id":"warner-bros-world-abu-dhabi","subtitle":"Parks","details":"Opened in 2018 on Yas Island, one of the world's largest indoor parks, with lands for Gotham City, Metropolis and Cartoon Junction.","image":"https://thumb.wikimedia.org/wikipedia/en/thumb/3/32/Warner_Bros._World_Abu_Dhabi_01.jpg/1280px-Warner_Bros._World_Abu_Dhabi_01.jpg"},{"name":"Ferrari World Abu Dhabi","rarity":"rare","id":"ferrari-world-abu-dhabi","subtitle":"Parks","details":"Opened in 2010 on Yas Island under a vast red roof shaped like a Ferrari profile, home to Formula Rossa, famed for its launch speed.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Formula_Rossa_coaster.jpg/1280px-Formula_Rossa_coaster.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Legoland California","rarity":"rare","id":"legoland-california","subtitle":"Parks","details":"Opened in 1999 in Carlsbad, California, the first Legoland in the Americas, built from millions of bricks beside a water park and aquarium.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Legoland_California_entrance_%285712056741%29.jpg/1280px-Legoland_California_entrance_%285712056741%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Legoland Florida","rarity":"rare","id":"legoland-florida","subtitle":"Parks","details":"Opened in 2011 in Winter Haven, Florida, on the historic Cypress Gardens site, preserving the botanical gardens within a brick-built park.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Winter_Haven_-_Legoland_Florida_-_Entrance_%289424257204%29.jpg/1280px-Winter_Haven_-_Legoland_Florida_-_Entrance_%289424257204%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Energylandia","rarity":"rare","id":"energylandia","subtitle":"Parks","details":"Opened in 2014 in Zator, Poland, growing rapidly from a small park into one of Europe's largest collections of roller coasters.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Energylandia_-_Entrance_%282018%29.jpg/1280px-Energylandia_-_Entrance_%282018%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Santa Cruz Beach Boardwalk","rarity":"rare","id":"santa-cruz-beach-boardwalk","subtitle":"Parks","details":"Opened in 1907 on the California coast, a seaside boardwalk park whose 1924 Giant Dipper wooden coaster is a National Historic Landmark.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Santa_Cruz_Beach_Boardwalk_2023-07-16_%281%29.jpg/1280px-Santa_Cruz_Beach_Boardwalk_2023-07-16_%281%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Dorney Park","rarity":"uncommon","id":"dorney-park","subtitle":"Parks","details":"Opened in 1884 in Allentown, Pennsylvania, one of America's oldest parks, evolving from a trout pond and picnic grove into a coaster park.","image":"https://upload.wikimedia.org/wikipedia/commons/7/76/1960_-_Dorney_Park_Entrance_-_Postcard_-_Allentown_PA.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Worlds of Fun","rarity":"uncommon","id":"worlds-of-fun","subtitle":"Parks","details":"Opened in 1973 in Kansas City, Missouri, themed to Jules Verne's Around the World in Eighty Days, with lands for five continents.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Worlds_of_Fun_2002_%283298442988%29.jpg/1280px-Worlds_of_Fun_2002_%283298442988%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Valleyfair","rarity":"uncommon","id":"valleyfair","subtitle":"Parks","details":"Opened in 1976 in Shakopee, Minnesota, the Upper Midwest's major park, set near the Minnesota River with a water park inside the gates.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Valleyfair%2C_Shakopee%2C_Minnesota_%2852358528378%29.jpg/1280px-Valleyfair%2C_Shakopee%2C_Minnesota_%2852358528378%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Michigan's Adventure","rarity":"uncommon","id":"michigans-adventure","subtitle":"Parks","details":"Opened in 1956 in Muskegon, Michigan, growing from a petting zoo into the state's largest park, anchored by the Shivering Timbers coaster.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Shivering_Timbers_airtime_hills_seen_from_the_midway%2C_June_2002_-_ThrillZing.jpg/1280px-Shivering_Timbers_airtime_hills_seen_from_the_midway%2C_June_2002_-_ThrillZing.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"La Ronde","rarity":"uncommon","id":"la-ronde","subtitle":"Parks","details":"Opened in 1967 in Montreal, Canada, built for Expo 67 on islands in the St. Lawrence River and still hosting fireworks competitions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Entrance_to_the_La_Ronde.jpg/1280px-Entrance_to_the_La_Ronde.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Six Flags Over Texas","rarity":"uncommon","id":"six-flags-over-texas","subtitle":"Parks","details":"Opened in 1961 in Arlington, Texas, the original Six Flags park, its name honoring the six flags that have flown over Texas.","image":"https://upload.wikimedia.org/wikipedia/commons/4/43/Six_Flags_over_Texas_%28Entrance%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Six Flags Fiesta Texas","rarity":"uncommon","id":"six-flags-fiesta-texas","subtitle":"Parks","details":"Opened in 1992 in San Antonio, Texas, built in a limestone quarry whose cliffs form a dramatic backdrop for its rides and shows.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Iron_Rattler_inversion.JPG/1280px-Iron_Rattler_inversion.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Six Flags Over Georgia","rarity":"uncommon","id":"six-flags-over-georgia","subtitle":"Parks","details":"Opened in 1967 near Atlanta, Georgia, the second Six Flags park, set in wooded hills west of the city.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Six_Flags_Over_Georgia_new_entrance_gate.jpg/1280px-Six_Flags_Over_Georgia_new_entrance_gate.jpg"},{"name":"Six Flags Discovery Kingdom","rarity":"uncommon","id":"six-flags-discovery-kingdom","subtitle":"Parks","details":"Opened in 1986 in Vallejo, California, combining marine life, animal exhibits and thrill rides north of San Francisco Bay.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Medusa_%28Six_Flags_Discovery_Kingdom%29_2.jpg/1280px-Medusa_%28Six_Flags_Discovery_Kingdom%29_2.jpg"},{"name":"Six Flags New England","rarity":"uncommon","id":"six-flags-new-england","subtitle":"Parks","details":"Opened in 1870 as a picnic park in Agawam, Massachusetts, among the oldest parks in America, on the banks of the Connecticut River.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/Riddler_Revenge_%28Six_Flags_New_England%29_1.jpg/1280px-Riddler_Revenge_%28Six_Flags_New_England%29_1.jpg"},{"name":"Motiongate Dubai","rarity":"uncommon","id":"motiongate-dubai","subtitle":"Parks","details":"Opened in 2016 in Dubai Parks and Resorts, a Hollywood-studio park with indoor and outdoor lands in the desert heat.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Motiongate_Dubai_-_41047320704.jpg/1280px-Motiongate_Dubai_-_41047320704.jpg"},{"name":"Legoland Billund","rarity":"uncommon","id":"legoland-billund","subtitle":"Parks","details":"Opened in 1968 in Billund, Denmark, beside the original Lego factory, the first Legoland, with Miniland models of world landmarks.","image":"https://upload.wikimedia.org/wikipedia/commons/1/11/LegoBillundTowerView.jpg"},{"name":"Legoland Windsor","rarity":"uncommon","id":"legoland-windsor","subtitle":"Parks","details":"Opened in 1996 on a former safari park site in Windsor, England, a hillside Legoland with views toward Windsor Castle.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Entrance_to_Legoland_Windsor.jpg/1280px-Entrance_to_Legoland_Windsor.jpg"},{"name":"Legoland New York","rarity":"uncommon","id":"legoland-new-york","subtitle":"Parks","details":"Opened in 2021 in Goshen, New York, the largest Legoland by land area, spread across seven themed lands in the Hudson Valley.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/LEGOLAND_New_York.jpg/1280px-LEGOLAND_New_York.jpg"},{"name":"Thorpe Park","rarity":"uncommon","id":"thorpe-park","subtitle":"Parks","details":"Opened in 1979 on a flooded gravel pit in Surrey, England, an island park aimed at thrill seekers, surrounded by water.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Colossus-Thorpe-1.jpg/1280px-Colossus-Thorpe-1.jpg"},{"name":"Chessington World of Adventures","rarity":"uncommon","id":"chessington-world-of-adventures","subtitle":"Parks","details":"Opened in 1987 in Surrey, England, combining a zoo dating to 1931 with themed ride lands southwest of London.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bb/AdventureTreeChessington.jpg"},{"name":"Walibi Holland","rarity":"uncommon","id":"walibi-holland","subtitle":"Parks","details":"Opened in 1971 in Biddinghuizen, Netherlands, a polder park that reinvented itself around high-thrill coasters and festivals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Walibi_Holland_entrance.JPG/1280px-Walibi_Holland_entrance.JPG"},{"name":"Walibi Belgium","rarity":"uncommon","id":"walibi-belgium","subtitle":"Parks","details":"Opened in 1975 in Wavre, Belgium, the original Walibi, named from the first letters of Wavre, Limal and Bierges.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Walibi_Belgium_-_Buzzsaw_%2803%29.JPG/1280px-Walibi_Belgium_-_Buzzsaw_%2803%29.JPG"},{"name":"Plopsaland De Panne","rarity":"uncommon","id":"plopsaland-de-panne","subtitle":"Parks","details":"Opened in 2000 on the Belgian coast at De Panne, built around Studio 100 television characters on a park site dating to 1935.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Ingang_Plopsaland_De_Panne_3.JPG/1280px-Ingang_Plopsaland_De_Panne_3.JPG"},{"name":"Bobbejaanland","rarity":"uncommon","id":"bobbejaanland","subtitle":"Parks","details":"Opened in 1961 in Lichtaart, Belgium, founded by singer Bobbejaan Schoepen as a music hall and lake resort that grew into a ride park.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Bobbejaanland_entry.jpg/1280px-Bobbejaanland_entry.jpg"},{"name":"Toverland","rarity":"uncommon","id":"toverland","subtitle":"Parks","details":"Opened in 2001 in Sevenum, Netherlands, starting as an indoor play park and expanding into richly themed outdoor lands.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Toverland_hoofdentree.jpg/1280px-Toverland_hoofdentree.jpg"},{"name":"Wiener Prater","rarity":"uncommon","id":"wiener-prater","subtitle":"Parks","details":"Vienna's public park in Austria, home to amusement rides since the 1800s and the 1897 Giant Ferris Wheel, a symbol of the city.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Wien%2C_Prater%2C_Riesenrad_--_2018_--_3161.jpg/1280px-Wien%2C_Prater%2C_Riesenrad_--_2018_--_3161.jpg"},{"name":"Bakken","rarity":"uncommon","id":"bakken","subtitle":"Parks","details":"Opened in 1583 in a deer park north of Copenhagen, Denmark, widely cited as the world's oldest operating amusement park.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Bakken_entry.jpg/1280px-Bakken_entry.jpg"},{"name":"Djurs Sommerland","rarity":"uncommon","id":"djurs-sommerland","subtitle":"Parks","details":"Opened in 1981 in Jutland, Denmark, a summerland park that grew into one of the country's largest, with themed lands in the countryside.","image":"https://upload.wikimedia.org/wikipedia/commons/2/23/Djurs-sommerland.jpg"},{"name":"Tibidabo Amusement Park","rarity":"uncommon","id":"tibidabo-amusement-park","subtitle":"Parks","details":"Opened in 1901 atop Mount Tibidabo above Barcelona, Spain, reached by funicular and famed for panoramic views over the city and sea.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/TibidaboBlocks.jpg/1280px-TibidaboBlocks.jpg"},{"name":"Parque Warner Madrid","rarity":"uncommon","id":"parque-warner-madrid","subtitle":"Parks","details":"Opened in 2002 in San Martin de la Vega, Spain, a movie park of studio streets and Gotham and cartoon lands southeast of Madrid.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Entrada-parque-warner.jpg/1280px-Entrada-parque-warner.jpg"},{"name":"Warner Bros. Movie World (Australia)","rarity":"uncommon","id":"warner-bros-movie-world-australia","subtitle":"Parks","details":"Opened in 1991 on Australia's Gold Coast, a working-studio park of movie streets, stunt shows and DC superhero areas.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Grand_Entrance_-_Warner_Bros._Movie_World.jpg/1280px-Grand_Entrance_-_Warner_Bros._Movie_World.jpg"},{"name":"Dreamworld","rarity":"uncommon","id":"dreamworld","subtitle":"Parks","details":"Opened in 1981 on Australia's Gold Coast, the country's largest park, paired with WhiteWater World and a tiger habitat.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a8/Dreamworld_and_WhiteWater_World_aerial_July_2011.jpg"},{"name":"Sea World (Gold Coast)","rarity":"uncommon","id":"sea-world-gold-coast","subtitle":"Parks","details":"Opened in 1971 on Australia's Gold Coast, a marine park on a narrow spit between the Pacific Ocean and the Broadwater.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Sea_world_australia.jpg"},{"name":"Luna Park Sydney","rarity":"uncommon","id":"luna-park-sydney","subtitle":"Parks","details":"Opened in 1935 beside Sydney Harbour Bridge in Australia, its giant smiling-face entrance is one of the harbour's landmarks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/2014-07-06_Luna_Park_Sydney_1.jpg/1280px-2014-07-06_Luna_Park_Sydney_1.jpg"},{"name":"Chimelong Ocean Kingdom","rarity":"uncommon","id":"chimelong-ocean-kingdom","subtitle":"Parks","details":"Opened in 2014 in Zhuhai, China, a marine park built around a whale shark aquarium and a nightly show over its central lagoon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/11144-Ocean-Kingdom.jpg/1280px-11144-Ocean-Kingdom.jpg"},{"name":"Genting SkyWorlds","rarity":"uncommon","id":"genting-skyworlds","subtitle":"Parks","details":"Opened in 2022 high in Malaysia's Genting Highlands, a hilltop park at 6,000 feet where rides often sit above the clouds.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Genting_SkyWorlds_Theme_Park.jpg/1280px-Genting_SkyWorlds_Theme_Park.jpg"},{"name":"Sunway Lagoon","rarity":"uncommon","id":"sunway-lagoon","subtitle":"Parks","details":"Opened in 1992 in Subang Jaya, Malaysia, a multi-park resort combining water slides, rides, wildlife and a surf beach near Kuala Lumpur.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Sunway_Lagoon_%28220711%29.jpg/1280px-Sunway_Lagoon_%28220711%29.jpg"},{"name":"Happy Valley (Beijing)","rarity":"uncommon","id":"happy-valley-beijing","subtitle":"Parks","details":"Opened in 2006 in Beijing, China, the flagship of a national chain of Happy Valley parks, themed to world civilizations.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Happy_Valley_Beijing_1.jpg/1280px-Happy_Valley_Beijing_1.jpg"},{"name":"VinWonders Phu Quoc","rarity":"uncommon","id":"vinwonders-phu-quoc","subtitle":"Parks","details":"Opened in 2020 on Phu Quoc island in Vietnam, a large park of themed zones beside a water park and aquarium resort complex.","image":"https://upload.wikimedia.org/wikipedia/commons/c/ce/VinWonders-Phu-Quoc.jpg"},{"name":"Silverwood Theme Park","rarity":"uncommon","id":"silverwood-theme-park","subtitle":"Parks","details":"Opened in 1988 in Athol, Idaho, the Pacific Northwest's largest park, grown from a private airstrip and vintage aircraft collection.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Roller_Coaster_Alley_%2850039116606%29.jpg/1280px-Roller_Coaster_Alley_%2850039116606%29.jpg"},{"name":"Adventureland (Iowa)","rarity":"uncommon","id":"adventureland-iowa","subtitle":"Parks","details":"Opened in 1974 near Des Moines, Iowa, a family park themed to an Iowa main street, with areas nodding to frontier and farm heritage.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Adventureland%2C_Iowa_train_station.jpg/1280px-Adventureland%2C_Iowa_train_station.jpg"},{"name":"Lagoon","rarity":"uncommon","id":"lagoon","subtitle":"Parks","details":"Opened in 1886 in Farmington, Utah, a family-owned park between the Great Salt Lake and the Wasatch Mountains.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0a/Lagoon_gardens.JPG"},{"name":"Bellewaerde","rarity":"common","id":"bellewaerde","subtitle":"Parks","details":"Opened in 1954 in Ypres, Belgium, starting as a zoo and safari park before adding rides among its gardens and animal habitats.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Bellewaerde_%28ingang_1%29.jpg/1280px-Bellewaerde_%28ingang_1%29.jpg"},{"name":"Duinrell","rarity":"common","id":"duinrell","subtitle":"Parks","details":"Opened in 1935 in Wassenaar, Netherlands, a wooded estate park paired with the Tikibad, one of Europe's best-known water slide complexes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Entrance_to_Duinrell%2C_Wassenaar_%282022%29_02.jpg/1280px-Entrance_to_Duinrell%2C_Wassenaar_%282022%29_02.jpg"},{"name":"Slagharen","rarity":"common","id":"slagharen","subtitle":"Parks","details":"Opened in 1963 in Overijssel, Netherlands, a Wild West-themed park that began as a pony park where guests rented ponies and carts.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Slagharen_-_ingang_-_2026.jpg/1280px-Slagharen_-_ingang_-_2026.jpg"},{"name":"Fårup Sommerland","rarity":"common","id":"farup-sommerland","subtitle":"Parks","details":"Opened in 1975 in northern Jutland, Denmark, a woodland summerland park repeatedly praised for its friendly, low-key atmosphere.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Farup_Sommerland_entrance.jpg/1280px-Farup_Sommerland_entrance.jpg"},{"name":"BonBon-Land","rarity":"common","id":"bonbon-land","subtitle":"Parks","details":"Opened in 1992 in Zealand, Denmark, a cheerfully gross-out park themed to BonBon candy characters, famous for its cheeky ride names.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d6/BonBon-Lands_forlystelse_Alba-Tossen.jpg"},{"name":"Walibi Rhône-Alpes","rarity":"common","id":"walibi-rhone-alpes","subtitle":"Parks","details":"Opened in 1979 in Les Avenieres, France, the French Walibi park, set in the countryside between Lyon and the Alps.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Entr%C3%A9e_Walibi_Rh%C3%B4ne-Alpes.JPG/1280px-Entr%C3%A9e_Walibi_Rh%C3%B4ne-Alpes.JPG"},{"name":"Isla Mágica","rarity":"common","id":"isla-magica","subtitle":"Parks","details":"Opened in 1997 in Seville, Spain, on part of the Expo 92 site, themed to the age of Spanish exploration of the Americas.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Entrada_a_Isla_M%C3%A1gica.JPG/1280px-Entrada_a_Isla_M%C3%A1gica.JPG"},{"name":"Terra Mítica","rarity":"common","id":"terra-mitica","subtitle":"Parks","details":"Opened in 2000 in Benidorm, Spain, a park themed to ancient Mediterranean civilizations, from Egypt and Greece to Rome and Iberia.","image":"https://upload.wikimedia.org/wikipedia/commons/2/21/Terra_Mitica_Benidorm.JPG"},{"name":"Luna Park Melbourne","rarity":"common","id":"luna-park-melbourne","subtitle":"Parks","details":"Opened in 1912 in St Kilda, Australia, entered through a giant Mr Moon face, with a scenic railway running since its opening era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Entrance_to_Melbourne%27s_Luna_Park_2014.jpg/1280px-Entrance_to_Melbourne%27s_Luna_Park_2014.jpg"},{"name":"Legoland Malaysia","rarity":"common","id":"legoland-malaysia","subtitle":"Parks","details":"Opened in 2012 in Johor, Malaysia, the first Legoland in Asia, with a Miniland built from bricks depicting Asian landmarks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Entrance_Legoland_Malaysia.jpg/1280px-Entrance_Legoland_Malaysia.jpg"},{"name":"Lake Compounce","rarity":"common","id":"lake-compounce","subtitle":"Parks","details":"Opened in 1846 in Bristol, Connecticut, cited as America's oldest continuously operating amusement park, beside a mountain lake.","image":"https://upload.wikimedia.org/wikipedia/commons/0/04/Lake_Compounce_Main_Gate.jpg"},{"name":"Canobie Lake Park","rarity":"common","id":"canobie-lake-park","subtitle":"Parks","details":"Opened in 1902 as a trolley park in Salem, New Hampshire, preserving classic rides including a 1930s wooden coaster on Canobie Lake.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Canobie_Lake_Park_Untamed.jpg/1280px-Canobie_Lake_Park_Untamed.jpg"},{"name":"Quassy Amusement Park","rarity":"common","id":"quassy-amusement-park","subtitle":"Parks","details":"Opened in 1908 in Middlebury, Connecticut, a small trolley-era park on Lake Quassapaug with a wooden coaster built for younger riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/YoYo_ride_at_Quassy_park.jpg/1280px-YoYo_ride_at_Quassy_park.jpg"},{"name":"Seabreeze Amusement Park","rarity":"common","id":"seabreeze-amusement-park","subtitle":"Parks","details":"Opened in 1879 in Rochester, New York, a lakeside park on Lake Ontario, home to the Jack Rabbit, a wooden coaster from 1920.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c4/Seabreeze-jackrabbit.jpg"},{"name":"Luna Park (Coney Island)","rarity":"common","id":"luna-park-coney-island","subtitle":"Parks","details":"Opened in 2010 on the historic Coney Island boardwalk in Brooklyn, New York, reviving the Luna Park name on the original amusement grounds.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Entrance_to_Luna_Park_Coney_Island.JPG/1280px-Entrance_to_Luna_Park_Coney_Island.JPG"},{"name":"Camden Park","rarity":"common","id":"camden-park","subtitle":"Parks","details":"Opened in 1903 as a trolley park in Huntington, West Virginia, preserving a 1950s wooden coaster and a classic haunted house ride.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Camden_Park_entrance_gate.jpg/1280px-Camden_Park_entrance_gate.jpg"},{"name":"Waldameer Park","rarity":"common","id":"waldameer-park","subtitle":"Parks","details":"Opened in 1896 in Erie, Pennsylvania, a trolley park on Lake Erie bluffs with free admission and a ravine-spanning wooden coaster.","image":"https://upload.wikimedia.org/wikipedia/commons/1/12/Waldameer_pavillion.JPG"},{"name":"DelGrosso's Park","rarity":"common","id":"delgrossos-park","subtitle":"Parks","details":"Opened in 1947 in Tipton, Pennsylvania, owned by the DelGrosso pasta sauce family, pairing a small ride park with famous Italian food.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/DelGrosso%E2%80%99s_Amusement_Park_-_panoramio_%281%29.jpg/1280px-DelGrosso%E2%80%99s_Amusement_Park_-_panoramio_%281%29.jpg"},{"name":"Idlewild","rarity":"common","id":"idlewild","subtitle":"Parks","details":"Opened in 1878 in Ligonier, Pennsylvania, a pastoral park of shaded groves that added a Story Book Forest of nursery-rhyme scenes in 1956.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/IDLEWILD_MR_ROGERS_TROLLEY_WIDE_200_6_00_8_-_panoramio.jpg/1280px-IDLEWILD_MR_ROGERS_TROLLEY_WIDE_200_6_00_8_-_panoramio.jpg"},{"name":"Dutch Wonderland","rarity":"common","id":"dutch-wonderland","subtitle":"Parks","details":"Opened in 1963 in Lancaster, Pennsylvania, a kingdom for kids fronted by a castle, set in the heart of Pennsylvania Dutch Country.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Dutch_Wonderland_w_spider_LanCo.jpg/1280px-Dutch_Wonderland_w_spider_LanCo.jpg"},{"name":"Story Land","rarity":"common","id":"story-land","subtitle":"Parks","details":"Opened in 1954 in Glen, New Hampshire, a storybook park in the White Mountains where nursery rhymes and fairy tales fill shaded paths.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Cinderella%27s_Castle%2C_Story_Land_theme_park_in_Glen%2C_NH.jpg/1280px-Cinderella%27s_Castle%2C_Story_Land_theme_park_in_Glen%2C_NH.jpg"},{"name":"Santa's Village (New Hampshire)","rarity":"common","id":"santas-village-new-hampshire","subtitle":"Parks","details":"Opened in 1953 in Jefferson, New Hampshire, a Christmas park in the White Mountains where Santa greets guests all summer long.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Santas_Village_Jefferson_New_Hampshire_Reindeer_Rendezvous.jpg/1280px-Santas_Village_Jefferson_New_Hampshire_Reindeer_Rendezvous.jpg"},{"name":"Funtown Splashtown USA","rarity":"common","id":"funtown-splashtown-usa","subtitle":"Parks","details":"Opened in 1967 in Saco, Maine, a family park pairing classic rides and a water park on the route to Maine's southern beaches.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Funtown-Splashtown_USA.jpg/1280px-Funtown-Splashtown_USA.jpg"},{"name":"Palace Playland","rarity":"common","id":"palace-playland","subtitle":"Parks","details":"Opened in 1902 in Old Orchard Beach, Maine, New England's only beachfront amusement park, steps from the pier and the Atlantic.","image":"https://upload.wikimedia.org/wikipedia/commons/0/08/OldOrchardBeach_FerrisWheel.jpg"},{"name":"Bay Beach Amusement Park","rarity":"common","id":"bay-beach-amusement-park","subtitle":"Parks","details":"Opened in 1892 in Green Bay, Wisconsin, a city-owned park where rides long cost a quarter, beside the Fox River and Green Bay.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Bay_Beach_Train_Depot.jpg/1280px-Bay_Beach_Train_Depot.jpg"},{"name":"Little Amerricka","rarity":"common","id":"little-amerricka","subtitle":"Parks","details":"Opened in 1991 in Marshall, Wisconsin, a nostalgic park of restored classic rides, many rescued from Chicago's Kiddieland and Riverview.","image":"https://upload.wikimedia.org/wikipedia/commons/2/23/LittleAmerrickaScrambler.jpg"},{"name":"Memphis Kiddie Park","rarity":"common","id":"memphis-kiddie-park","subtitle":"Parks","details":"Opened in 1952 in Brooklyn, Ohio, a tiny kiddieland preserving miniature rides, including a steel coaster from its opening year.","image":"https://upload.wikimedia.org/wikipedia/commons/8/89/Little_Dipper_front.jpg"},{"name":"Arnolds Park","rarity":"common","id":"arnolds-park","subtitle":"Parks","details":"Opened in 1889 on Lake Okoboji in Iowa, a lakeside park whose 1930 wooden Legend coaster circles the park's heart.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Arnolds-Park-From-Lake.jpg"},{"name":"Oaks Amusement Park","rarity":"common","id":"oaks-amusement-park","subtitle":"Parks","details":"Opened in 1905 in Portland, Oregon, a trolley park on the Willamette River with one of America's oldest roller skating rinks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Oaks_Amusement_Park_entrance_Portland_Oregon.jpg/1280px-Oaks_Amusement_Park_entrance_Portland_Oregon.jpg"},{"name":"Enchanted Forest (Oregon)","rarity":"common","id":"enchanted-forest-oregon","subtitle":"Parks","details":"Opened in 1971 near Turner, Oregon, a hand-built storybook park where founder Roger Tofte sculpted fairy-tale scenes into a hillside.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Enchanted_Forest_Oregon_village.JPG/1280px-Enchanted_Forest_Oregon_village.JPG"},{"name":"Gilroy Gardens","rarity":"common","id":"gilroy-gardens","subtitle":"Parks","details":"Opened in 2001 in Gilroy, California, a garden park built around sculpted circus trees grafted into living shapes decades earlier.","image":"https://upload.wikimedia.org/wikipedia/commons/8/82/Circus_Tree_at_Gilroy_Gardens.jpg"},{"name":"Children's Fairyland","rarity":"common","id":"childrens-fairyland","subtitle":"Parks","details":"Opened in 1950 in Oakland, California, a storybook park for young children that helped inspire Walt Disney while planning Disneyland.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Fairyland_shoe_entrance.jpg/1280px-Fairyland_shoe_entrance.jpg"},{"name":"Belmont Park","rarity":"common","id":"belmont-park","subtitle":"Parks","details":"Opened in 1925 in Mission Beach, San Diego, a beachfront park centered on the Giant Dipper, a wooden coaster from its opening year.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Giant_Dipper_Roller_Coaster.jpg/1280px-Giant_Dipper_Roller_Coaster.jpg"},{"name":"Glenwood Caverns Adventure Park","rarity":"common","id":"glenwood-caverns-adventure-park","subtitle":"Parks","details":"Opened in 2003 on a mountaintop in Glenwood Springs, Colorado, reached by gondola, pairing cave tours with cliff-edge thrill rides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Glenwood_springs%2C_Caverns_Adventure_Park_-_panoramio.jpg/1280px-Glenwood_springs%2C_Caverns_Adventure_Park_-_panoramio.jpg"},{"name":"Lakeside Amusement Park","rarity":"common","id":"lakeside-amusement-park","subtitle":"Parks","details":"Opened in 1908 in Lakeside, Colorado, an Art Deco park glowing with neon beside Lake Rhoda, among America's best-preserved trolley parks.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ea/Tower_of_Jewels%2C_Lakeside_Amusement_Park%2C_Lakeside%2C_Colorado%2C_USA.jpg"},{"name":"Elitch Gardens","rarity":"common","id":"elitch-gardens","subtitle":"Parks","details":"Opened in 1890 in Denver, Colorado, starting as a zoological garden and theatre before growing into the city's downtown theme park.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Elitch_Gardens_Theme_Park_entrance%2C_Denver%2C_2009.jpg/1280px-Elitch_Gardens_Theme_Park_entrance%2C_Denver%2C_2009.jpg"},{"name":"Lake Winnepesaukah","rarity":"common","id":"lake-winnepesaukah","subtitle":"Parks","details":"Opened in 1925 in Rossville, Georgia, a family park on a spring-fed lake, known to generations of Chattanooga-area guests as Lake Winnie.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Entrance_to_Lake_Winnepesaukah_Amusement_Park%2C_Rossville%2C_Georgia.jpg/1280px-Entrance_to_Lake_Winnepesaukah_Amusement_Park%2C_Rossville%2C_Georgia.jpg"},{"name":"Fun Spot America (Atlanta)","rarity":"common","id":"fun-spot-america-atlanta","subtitle":"Parks","details":"Opened in 1990 in Fayetteville, Georgia, a family fun center turned ride park, home to a major wooden coaster added in 2022.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Fun_Spot_America_Atlanta_%2852994227152%29.jpg/1280px-Fun_Spot_America_Atlanta_%2852994227152%29.jpg"},{"name":"Alabama Adventure","rarity":"common","id":"alabama-adventure","subtitle":"Parks","details":"Opened in 1998 in Bessemer, Alabama, a ride and water park built around a wooden coaster named for the state's wild Rampage legend.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Rampage_%28Alabama_Adventure%29_1.jpg/1280px-Rampage_%28Alabama_Adventure%29_1.jpg"},{"name":"Castle Park","rarity":"common","id":"castle-park","subtitle":"Parks","details":"Opened in 1976 in Riverside, California, built by miniature golf pioneer Bud Hurlbut around a castle arcade and landscaped courses.","image":"https://upload.wikimedia.org/wikipedia/commons/6/62/Castle_Amusement%2C_candy_house%2C_Riverside%2C_California_LOC_36681187684.jpg"},{"name":"Cliff's Amusement Park","rarity":"common","id":"cliffs-amusement-park","subtitle":"Parks","details":"Opened in 1959 in Albuquerque, New Mexico, a desert park on Route 66 heritage ground, with a wooden coaster among its rides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Cliff%27s_Amusement_Park_entrance_gate.jpg/1280px-Cliff%27s_Amusement_Park_entrance_gate.jpg"},{"name":"Frontier City","rarity":"common","id":"frontier-city","subtitle":"Parks","details":"Opened in 1958 in Oklahoma City, Oklahoma, a Western-themed park that began as a recreated frontier town street of shops and shows.","image":"https://upload.wikimedia.org/wikipedia/commons/d/dd/Frontier_City.jpg"},{"name":"Mount Olympus Theme Park","rarity":"common","id":"mount-olympus-theme-park","subtitle":"Parks","details":"Opened in 2004 in Wisconsin Dells, Wisconsin, a Greek-mythology park grown from go-kart tracks in the Midwest's water park capital.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/CyclopsMt.OlympusWater%26ThemePark.jpg/1280px-CyclopsMt.OlympusWater%26ThemePark.jpg"},{"name":"Wild Adventures","rarity":"common","id":"wild-adventures","subtitle":"Parks","details":"Opened in 1996 in Valdosta, Georgia, a park combining rides with a large animal collection, started as a farm and petting zoo.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Horizon_Wheel%2C_Wild_Adventures.jpg/1280px-Horizon_Wheel%2C_Wild_Adventures.jpg"},{"name":"Haunted Mansion","rarity":"legendary","id":"haunted-mansion","subtitle":"Dark Rides & Classic Attractions","details":"999 happy haunts materialize in this Omnimover ghost tour, first opened at Disneyland in 1969 with a stretching room, seance circle and hitchhiking ghosts.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Haunted_Mansion%2C_Disneyland%2C_CA.jpg/1280px-Haunted_Mansion%2C_Disneyland%2C_CA.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Pirates of the Caribbean","rarity":"legendary","id":"pirates-of-the-caribbean","subtitle":"Dark Rides & Classic Attractions","details":"A boat voyage past auctioneers, a burning town and Captain Jack Sparrow, first opened at Disneyland in 1967 as the last ride Walt Disney personally supervised.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Disneyland-POTC_entrance.jpg/960px-Disneyland-POTC_entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"It's a Small World","rarity":"legendary","id":"its-a-small-world","subtitle":"Dark Rides & Classic Attractions","details":"Mary Blair's singing children sail past in boats on this gentle voyage of world unity, created for the 1964 New York World's Fair and moved to Disneyland in 1966.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/%22it%27s_a_small_world%22_Facade_and_Entrance_Sign%2C_June_2025.jpg/1280px-%22it%27s_a_small_world%22_Facade_and_Entrance_Sign%2C_June_2025.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Indiana Jones Adventure","rarity":"legendary","id":"indiana-jones-adventure","subtitle":"Dark Rides & Classic Attractions","details":"A rugged troop transport races a giant rolling boulder and a cursed temple idol in this enhanced motion vehicle ride, opened at Disneyland in 1995.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Indiana_Jones_temple%2C_Disneyland.jpg/960px-Indiana_Jones_temple%2C_Disneyland.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Journey to the Center of the Earth","rarity":"legendary","id":"journey-to-the-center-of-the-earth","subtitle":"Dark Rides & Classic Attractions","details":"Subterranean vehicles dive through glowing caverns and flee a lava monster in Tokyo DisneySea's signature ride, built inside the volcano of Mysterious Island.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Journey_to_the_Center_of_the_Earth_Tokyo_DisneySea_01.jpg/1280px-Journey_to_the_Center_of_the_Earth_Tokyo_DisneySea_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Star Wars: Rise of the Resistance","rarity":"legendary","id":"star-wars-rise-of-the-resistance","subtitle":"Dark Rides & Classic Attractions","details":"Trackless transports are captured by a Star Destroyer in this multi-stage adventure with a prison break, AT-AT walkers and a drop escape, opened in 2019.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Ride_Vehicle_%2852934564699%29.jpg/1280px-Ride_Vehicle_%2852934564699%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Tower of Terror","rarity":"legendary","id":"tower-of-terror","subtitle":"Dark Rides & Classic Attractions","details":"A freight elevator drops riders through a haunted Hollywood hotel in this drop tower, opened at Walt Disney World in 1994 and retold at parks worldwide.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Hollywood_Tower_Hotel.jpg/1280px-Hollywood_Tower_Hotel.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Avatar Flight of Passage","rarity":"legendary","id":"avatar-flight-of-passage","subtitle":"Dark Rides & Classic Attractions","details":"Riders link to an avatar and soar on a banshee over Pandora's floating mountains in this simulator, the centerpiece of Pandora at Disney's Animal Kingdom since 2017.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Avatar_Flight_of_Passage_-_Disney%27s_Animal_Kingdom.jpg/1280px-Avatar_Flight_of_Passage_-_Disney%27s_Animal_Kingdom.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"The Amazing Adventures of Spider-Man","rarity":"legendary","id":"the-amazing-adventures-of-spider-man","subtitle":"Dark Rides & Classic Attractions","details":"A 3D motion-base ride through New York as Spider-Man battles Doc Ock and the Sinister Syndicate, opened at Universal Islands of Adventure in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/The_Amazing_Adventures_of_Spider-Man_entrance_1.jpg/1280px-The_Amazing_Adventures_of_Spider-Man_entrance_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Jungle Cruise","rarity":"legendary","id":"jungle-cruise","subtitle":"Dark Rides & Classic Attractions","details":"Skippers pilot boats past hippos, headhunters and the back side of water on this river expedition, an opening-day Disneyland attraction from 1955.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Jungle_Cruise_Entrance_Sunset.JPG/960px-Jungle_Cruise_Entrance_Sunset.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Mystic Manor","rarity":"epic","id":"mystic-manor","subtitle":"Dark Rides & Classic Attractions","details":"Lord Henry Mystic's monkey Albert unleashes a magical music box on a trackless tour of a Hong Kong Disneyland mansion, opened in 2013 with a Danny Elfman score.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Disneyland_Hong_Kong_Mystic_Manor_IMG_5474.JPG/1280px-Disneyland_Hong_Kong_Mystic_Manor_IMG_5474.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Radiator Springs Racers","rarity":"epic","id":"radiator-springs-racers","subtitle":"Dark Rides & Classic Attractions","details":"Convertibles tour Ornament Valley then race side by side through Radiator Springs in this slot-car dark ride, the star of Cars Land at California Adventure since 2012.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Radiator_Springs_Racers_%2818406621499%29.jpg/1280px-Radiator_Springs_Racers_%2818406621499%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Soarin'","rarity":"epic","id":"soarin","subtitle":"Dark Rides & Classic Attractions","details":"Hang gliders lift toward a giant screen for flights over world landmarks, first as Soarin' Over California in 2001 and later re-filmed as Soarin' Around the World.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Soarin%27_Around_the_World_Opening_Day_%2827127684434%29.jpg/1280px-Soarin%27_Around_the_World_Opening_Day_%2827127684434%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Mickey & Minnie's Runaway Railway","rarity":"epic","id":"mickey-and-minnies-runaway-railway","subtitle":"Dark Rides & Classic Attractions","details":"A trackless train bursts through a cartoon short on this ride through Runnamuck Park, opened at Hollywood Studios in 2020 starring Mickey and Minnie.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Mickey_%26_Minnie%27s_Runaway_Railway_%28Disney%27s_Hollywood_Studios%29_1.jpg/1280px-Mickey_%26_Minnie%27s_Runaway_Railway_%28Disney%27s_Hollywood_Studios%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Remy's Ratatouille Adventure","rarity":"epic","id":"remys-ratatouille-adventure","subtitle":"Dark Rides & Classic Attractions","details":"Trackless mouse cars scurry under Gusteau's kitchen floor in this 4D dark ride, first opened at Walt Disney Studios Park in Paris in 2014.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Remy%27s_Ratatouille_Adventure.jpg/960px-Remy%27s_Ratatouille_Adventure.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Frozen Ever After","rarity":"epic","id":"frozen-ever-after","subtitle":"Dark Rides & Classic Attractions","details":"Boats sail to Elsa's ice palace past Olaf, Sven and a singing Anna in this flume dark ride, opened in Epcot's Norway pavilion in 2016.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Frozen_Ever_After_Sign_%2827803925036%29.jpg/1280px-Frozen_Ever_After_Sign_%2827803925036%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Peter Pan's Flight","rarity":"epic","id":"peter-pans-flight","subtitle":"Dark Rides & Classic Attractions","details":"Flying pirate ships soar over London rooftops to Never Land in this suspended dark ride, an opening-day Disneyland attraction from 1955.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Peter_Pan%27s_Flight_%2834399881866%29.jpg/1280px-Peter_Pan%27s_Flight_%2834399881866%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"E.T. Adventure","rarity":"epic","id":"e-t-adventure","subtitle":"Dark Rides & Classic Attractions","details":"Bicycles fly across the moon to save E.T.'s dying Green Planet in this dark ride, the last original opening-day attraction left at Universal Studios Florida.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/ET_Adventure_facade_1.jpg/1280px-ET_Adventure_facade_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Transformers: The Ride","rarity":"epic","id":"transformers-the-ride","subtitle":"Dark Rides & Classic Attractions","details":"Motion-base vehicles race through a Decepticon attack on the AllSpark in this 3D simulator ride, first opened at Universal Studios Singapore in 2011.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Transformers_The_Ride_%28Universal_Studios_Hollywood%29_1.jpg/1280px-Transformers_The_Ride_%28Universal_Studios_Hollywood%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Symbolica","rarity":"epic","id":"symbolica","subtitle":"Dark Rides & Classic Attractions","details":"Trackless cars tour the magical palace of King Pardulfus in Efteling's signature dark ride, opened in 2017 for the park's 65th anniversary.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Symbolica_%28Efteling%29_20170521.jpg/1280px-Symbolica_%28Efteling%29_20170521.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Droomvlucht","rarity":"epic","id":"droomvlucht","subtitle":"Dark Rides & Classic Attractions","details":"Suspended gondolas float through forests of fairies, trolls and floating castles in Efteling's Dream Flight, opened in 1993 and long voted among its best-loved rides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Droomvlucht_entrance_Efteling.jpg/1280px-Droomvlucht_entrance_Efteling.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Millennium Falcon: Smugglers Run","rarity":"epic","id":"millennium-falcon-smugglers-run","subtitle":"Dark Rides & Classic Attractions","details":"Six riders pilot the Falcon as pilots, gunners and engineers on a smuggling run for Hondo Ohnaka in this interactive simulator, opened in Galaxy's Edge in 2019.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Millennium_Falcon_on_Batuu_%2852934802163%29.jpg/1280px-Millennium_Falcon_on_Batuu_%2852934802163%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Test Track","rarity":"epic","id":"test-track","subtitle":"Dark Rides & Classic Attractions","details":"Guests design a concept car then put it through handling, efficiency and a high-speed outdoor loop in this slot-car thrill ride at Epcot, first opened in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Test_Track_entrance_2010.jpg/1280px-Test_Track_entrance_2010.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Tiana's Bayou Adventure","rarity":"epic","id":"tianas-bayou-adventure","subtitle":"Dark Rides & Classic Attractions","details":"Log flumes float through a Mardi Gras celebration with Tiana, Louis and new critter musicians in this reimagining of the classic Splash Mountain flume, opened in 2024.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Tiana%27s_Bayou_Adventure_The_Magic_Kingdom_-_54164491348.jpg/1280px-Tiana%27s_Bayou_Adventure_The_Magic_Kingdom_-_54164491348.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Mr. Toad's Wild Ride","rarity":"rare","id":"mr-toads-wild-ride","subtitle":"Dark Rides & Classic Attractions","details":"Motorcars crash through Toad Hall, a courtroom and a fiery finale in this wild dark ride, surviving only at Disneyland as an opening-day 1955 original.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Mr._Toad%27s_Wild_Ride_at_Disneyland_in_2026.jpg/1280px-Mr._Toad%27s_Wild_Ride_at_Disneyland_in_2026.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Men in Black: Alien Attack","rarity":"rare","id":"men-in-black-alien-attack","subtitle":"Dark Rides & Classic Attractions","details":"Recruits zap swarming aliens for points aboard spinning vehicles in this interactive shooter ride, opened at Universal Studios Florida in 2000.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Men_in_Black_Alien_Attack_sign.jpg/1280px-Men_in_Black_Alien_Attack_sign.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Jurassic Park River Adventure","rarity":"rare","id":"jurassic-park-river-adventure","subtitle":"Dark Rides & Classic Attractions","details":"River rafts drift past gentle dinosaurs before a T. rex forces an 85-foot plunge in this flume ride, opened at Universal Islands of Adventure in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Jurassic_Park_River_Adventure_13.jpg/1280px-Jurassic_Park_River_Adventure_13.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"DINOSAUR","rarity":"rare","id":"dinosaur","subtitle":"Dark Rides & Classic Attractions","details":"Time Rovers bounce through a dark Cretaceous forest chasing an Iguanodon as a meteor closes in, opened at Disney's Animal Kingdom in 1998 as Countdown to Extinction.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/DINOSAUR_ride_entrance_sign%2C_The_Dino_Institute%2C_Disney%27s_Animal_Kingdom%2C_June_2006_-_ThrillZing.jpg/1280px-DINOSAUR_ride_entrance_sign%2C_The_Dino_Institute%2C_Disney%27s_Animal_Kingdom%2C_June_2006_-_ThrillZing.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kali River Rapids","rarity":"rare","id":"kali-river-rapids","subtitle":"Dark Rides & Classic Attractions","details":"Circular rafts spin down the Chakranadi River past logging and a burning forest in this whitewater ride at Disney's Animal Kingdom, opened in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Disney-Animal-Kingdom-Kali-River-Ride-8319.jpg/1280px-Disney-Animal-Kingdom-Kali-River-Ride-8319.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Grizzly River Run","rarity":"rare","id":"grizzly-river-run","subtitle":"Dark Rides & Classic Attractions","details":"Eight-person rafts whirl down a California gold-country river and drop through a spinning finale on this rapids ride at California Adventure, opened in 2001.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Grizzly_River_Run_-_DCA.JPG/1280px-Grizzly_River_Run_-_DCA.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kilimanjaro Safaris","rarity":"rare","id":"kilimanjaro-safaris","subtitle":"Dark Rides & Classic Attractions","details":"Open-air trucks cross a 110-acre savanna of elephants, lions and giraffes in this guided safari tour, opened at Disney's Animal Kingdom in 1998.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/On_Kilimanjaro_Safaris_vehicle.JPG/1280px-On_Kilimanjaro_Safaris_vehicle.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Living with the Land","rarity":"rare","id":"living-with-the-land","subtitle":"Dark Rides & Classic Attractions","details":"Boats glide from rainforest and desert scenes into working greenhouses growing Mickey-shaped pumpkins in this slow Epcot voyage, opened in 1982.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Living_with_the_Land_10.jpg/1280px-Living_with_the_Land_10.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Walt Disney's Carousel of Progress","rarity":"rare","id":"walt-disneys-carousel-of-progress","subtitle":"Dark Rides & Classic Attractions","details":"A rotating theatre follows one family through a century of household inventions to the Great Big Beautiful Tomorrow, created for the 1964 World's Fair.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Walt_Disney%27s_Carousel_of_Progress_%2829419642074%29.jpg/1280px-Walt_Disney%27s_Carousel_of_Progress_%2829419642074%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Walt Disney's Enchanted Tiki Room","rarity":"rare","id":"walt-disneys-enchanted-tiki-room","subtitle":"Dark Rides & Classic Attractions","details":"Audio-Animatronic birds Jose, Michael, Pierre and Fritz sing among tikis and flowers in this tropical show, opened at Disneyland in 1963.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Enchanted_Tiki_Room_Sign_%287192666744%29.jpg/1280px-Enchanted_Tiki_Room_Sign_%287192666744%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Fata Morgana","rarity":"rare","id":"fata-morgana","subtitle":"Dark Rides & Classic Attractions","details":"Boats drift through an Arabian Nights city of sultans, tigers and a giant djinn in Efteling's Forbidden City dark ride, opened in 1986.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Fata_Morgana_%28Efteling%29P1660024.jpg/1280px-Fata_Morgana_%28Efteling%29P1660024.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Villa Volta","rarity":"rare","id":"villa-volta","subtitle":"Dark Rides & Classic Attractions","details":"Efteling's madhouse flips riders' sense of up and down inside the cursed house of bandit Hugo, opened in 1996 as the first modern madhouse of its kind.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Efteling_Villa_Volta_01.jpg/1280px-Efteling_Villa_Volta_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Hex","rarity":"rare","id":"hex","subtitle":"Dark Rides & Classic Attractions","details":"Alton Towers' madhouse spins the legend of a chained oak and a beggar's curse inside the ruined towers, opened in 2000 in the park's historic house.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Alton_Towers_-_Hex.jpg/1280px-Alton_Towers_-_Hex.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Valhalla","rarity":"rare","id":"valhalla","subtitle":"Dark Rides & Classic Attractions","details":"Boats brave fire, ice and waterfalls through a Viking afterlife in Blackpool Pleasure Beach's vast indoor water dark ride, opened in 2000.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/Valhalla_Blackpool_Pleasure_Beach_%282023%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Wallace & Gromit's Thrill-O-Matic","rarity":"rare","id":"wallace-and-gromits-thrill-o-matic","subtitle":"Dark Rides & Classic Attractions","details":"Teacup-style cars ride through scenes from Wallace and Gromit's films, from A Close Shave to a giant penguin, opened at Blackpool Pleasure Beach in 2013.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Wallace_%26_Gromit%27s_Thrill-O-Matic.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Harry Potter and the Forbidden Journey","rarity":"rare","id":"harry-potter-and-the-forbidden-journey","subtitle":"Dark Rides & Classic Attractions","details":"Robotic-arm benches fly through Hogwarts, past dementors and a Quidditch match in this motion dark ride, opened at Universal Islands of Adventure in 2010.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Universal-Islands-of-Adventure-Harry-Potter-Castle-8892i.jpg/1280px-Universal-Islands-of-Adventure-Harry-Potter-Castle-8892i.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Skull Island: Reign of Kong","rarity":"rare","id":"skull-island-reign-of-kong","subtitle":"Dark Rides & Classic Attractions","details":"Expedition trucks cross a jungle island of dinosaurs before King Kong battles a Vastatosaurus in this 3D dark ride, opened at Islands of Adventure in 2016.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Skull_Island_Entrance_%2824315063928%29.jpg/1280px-Skull_Island_Entrance_%2824315063928%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Popeye & Bluto's Bilge-Rat Barges","rarity":"rare","id":"popeye-and-blutos-bilge-rat-barges","subtitle":"Dark Rides & Classic Attractions","details":"Spinning river rafts soak riders under waterfalls and through Popeye's boathouse on this rapids ride at Universal Islands of Adventure, opened in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Popeye_and_Blutos_Bilge-Rat_Barges_08.jpg/1280px-Popeye_and_Blutos_Bilge-Rat_Barges_08.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Dudley Do-Right's Ripsaw Falls","rarity":"rare","id":"dudley-do-rights-ripsaw-falls","subtitle":"Dark Rides & Classic Attractions","details":"Log flumes chase Snidely Whiplash through a cartoon lumber camp before plunging through a dynamite shack on this Islands of Adventure flume, opened in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Ripsaw_Falls_at_Islands_of_Adventure.jpg/1280px-Ripsaw_Falls_at_Islands_of_Adventure.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Gran Fiesta Tour","rarity":"rare","id":"gran-fiesta-tour","subtitle":"Dark Rides & Classic Attractions","details":"Boats sail past Mexico pavilion scenes hunting Donald Duck with Jose and Panchito of The Three Caballeros in this gentle Epcot dark ride, rethemed in 2007.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Gran_Fiesta_Tour_Starring_The_Three_Caballeros.jpg/1280px-Gran_Fiesta_Tour_Starring_The_Three_Caballeros.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Tomorrowland Transit Authority PeopleMover","rarity":"rare","id":"tomorrowland-transit-authority-peoplemover","subtitle":"Dark Rides & Classic Attractions","details":"Quiet trains glide through Space Mountain and Tomorrowland model cities on this elevated tour, descended from Disneyland's 1967 PeopleMover at Magic Kingdom.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Wdw-peoplemover.jpg/1280px-Wdw-peoplemover.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Toy Story Mania!","rarity":"rare","id":"toy-story-mania","subtitle":"Dark Rides & Classic Attractions","details":"Spring-action shooters spin riders through carnival games of ring tosses and balloon darts with Woody and Buzz in this 4D interactive ride, opened in 2008.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Toy_Story_Mania_%28Disney%27s_Hollywood_Studios%29_1.jpg/1280px-Toy_Story_Mania_%28Disney%27s_Hollywood_Studios%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"The Hall of Presidents","rarity":"uncommon","id":"the-hall-of-presidents","subtitle":"Dark Rides & Classic Attractions","details":"Audio-Animatronic presidents fill a grand theatre at Magic Kingdom, where a roll call of officeholders has anchored Liberty Square since 1971.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Hall_of_Presidents_MK.JPG/1280px-Hall_of_Presidents_MK.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"The Simpsons Ride","rarity":"uncommon","id":"the-simpsons-ride","subtitle":"Dark Rides & Classic Attractions","details":"A simulator coaster-car careens through Krustyland as Sideshow Bob sabotages the park in this Springfield flight simulator, opened at Universal parks in 2008.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Exterior_of_the_newly-opened_Simpsons_Ride_at_Universal_Studios_Hollywood.jpg/1280px-Exterior_of_the_newly-opened_Simpsons_Ride_at_Universal_Studios_Hollywood.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Despicable Me Minion Mayhem","rarity":"uncommon","id":"despicable-me-minion-mayhem","subtitle":"Dark Rides & Classic Attractions","details":"Motion simulators recruit riders as Minions and spin them through Gru's laboratory in this 3D family ride, opened at Universal Studios Florida in 2012.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Despicable_Me_Minion_Mayhem_at_Universal_Studios%2C_Orlando_%2837491242606%29.jpg/960px-Despicable_Me_Minion_Mayhem_at_Universal_Studios%2C_Orlando_%2837491242606%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Buzz Lightyear's Space Ranger Spin","rarity":"uncommon","id":"buzz-lightyears-space-ranger-spin","subtitle":"Dark Rides & Classic Attractions","details":"Two-person cruisers spin and fire laser cannons at Emperor Zurg's targets in this interactive Tomorrowland dark ride, opened at Magic Kingdom in 1998.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Buzz_Lightyear%27s_Space_Ranger_Spin.jpg/1280px-Buzz_Lightyear%27s_Space_Ranger_Spin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Snow White's Enchanted Wish","rarity":"uncommon","id":"snow-whites-enchanted-wish","subtitle":"Dark Rides & Classic Attractions","details":"Mine cars follow Snow White from the Evil Queen's dungeon to the dwarfs' cottage in this gentle dark ride, reimagined at Disneyland in 2021.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Snow_White%27s_Enchanted_Wish_%28Disneyland%29_1.jpg/1280px-Snow_White%27s_Enchanted_Wish_%28Disneyland%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Alice in Wonderland","rarity":"uncommon","id":"alice-in-wonderland","subtitle":"Dark Rides & Classic Attractions","details":"Caterpillar cars tumble down the rabbit hole past the Cheshire Cat and Queen of Hearts in this two-level Disneyland dark ride, opened in 1958.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Alice_in_Wonderland_ride_vehicles.jpg/1280px-Alice_in_Wonderland_ride_vehicles.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Roger Rabbit's Car Toon Spin","rarity":"uncommon","id":"roger-rabbits-car-toon-spin","subtitle":"Dark Rides & Classic Attractions","details":"Spinning taxi cabs whirl through Toontown hunting Jessica Rabbit past weasels and the Dip in this Disneyland dark ride, opened in 1994.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Roger_Rabbit%27s_Car_Toon_Spin_2.jpg/1280px-Roger_Rabbit%27s_Car_Toon_Spin_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"The Many Adventures of Winnie the Pooh","rarity":"uncommon","id":"the-many-adventures-of-winnie-the-pooh","subtitle":"Dark Rides & Classic Attractions","details":"Hunny pots bounce through the Hundred Acre Wood on a blustery day with Tigger and Heffalumps in this family dark ride, opened at Magic Kingdom in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/The_Many_Adventures_of_Winnie_the_Pooh_%28attraction%29.jpg/1280px-The_Many_Adventures_of_Winnie_the_Pooh_%28attraction%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Under the Sea: Journey of The Little Mermaid","rarity":"uncommon","id":"under-the-sea-journey-of-the-little-mermaid","subtitle":"Dark Rides & Classic Attractions","details":"Clamshell Omnimovers descend under the sea to Ariel's grotto and Ursula's lair in this musical dark ride, opened at Magic Kingdom in 2012.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Under_the_Sea_Journey_of_the_Little_Mermaid_-_Magic_Kingdom.jpg/1280px-Under_the_Sea_Journey_of_the_Little_Mermaid_-_Magic_Kingdom.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Luigi's Rollickin' Roadsters","rarity":"uncommon","id":"luigis-rollickin-roadsters","subtitle":"Dark Rides & Classic Attractions","details":"Trackless dancing cars spin and twirl in choreographed patterns with Luigi's cousins from Carsoli in this Cars Land ride, opened at California Adventure in 2016.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luigi%27s%20Rollickin%27%20Roadsters%201.jpg?width=1024"},{"name":"Mater's Junkyard Jamboree","rarity":"uncommon","id":"maters-junkyard-jamboree","subtitle":"Dark Rides & Classic Attractions","details":"Baby tractors whip trailers around a junkyard dance floor to Mater's square-dance songs in this spinning Cars Land ride, opened in 2012.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mater%27s%20Junkyard%20Jamboree%20%287476935978%29.jpg?width=1024"},{"name":"Carnaval Festival","rarity":"uncommon","id":"carnaval-festival","subtitle":"Dark Rides & Classic Attractions","details":"Slow cars pass singing dolls in traditional dress from countries around the world in Efteling's cheerful dark ride, opened in 1984 with music by Ruud Bos.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Efteling%20Carnaval%20Festival%2004.jpg?width=1024"},{"name":"Pagode","rarity":"uncommon","id":"pagode","subtitle":"Dark Rides & Classic Attractions","details":"Efteling's Thai temple rises and rotates high above the park for panoramic views in this flying pagoda observation ride, opened in 1981.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Efteling%20Pagode.jpg?width=1024"},{"name":"Gondoletta","rarity":"uncommon","id":"gondoletta","subtitle":"Dark Rides & Classic Attractions","details":"Flat-bottomed boats drift on a tow cable around Efteling's ponds and gardens in this peaceful tow boat ride, opened in 1981.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Efteling%20Gondoletta%202.jpg?width=1024"},{"name":"Geisterschloss","rarity":"uncommon","id":"geisterschloss","subtitle":"Dark Rides & Classic Attractions","details":"Europa-Park's ghost castle sends gondolas past skeletons, crypts and a vampire ballroom in this Italian-themed haunted dark ride, opened in 1982.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Europa-Park%20-%20Ch%C3%A2teau%20hant%C3%A9%20%2801%29.JPG?width=1024"},{"name":"Journey into Imagination with Figment","rarity":"uncommon","id":"journey-into-imagination-with-figment","subtitle":"Dark Rides & Classic Attractions","details":"Tour cars follow the purple dragon Figment through sensory labs that celebrate imagination in this Epcot dark ride, in its current form since 2002.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Journey%20Into%20Imagination%20with%20Figment%204.jpg?width=1024"},{"name":"The Seas with Nemo & Friends","rarity":"uncommon","id":"the-seas-with-nemo-and-friends","subtitle":"Dark Rides & Classic Attractions","details":"Clamobiles drift through a coral reef with Nemo, Dory and Crush, ending beside a giant aquarium in this Epcot Omnimover ride, opened in 2007.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Seas%20at%20EPCOT%202024.jpg?width=1024"},{"name":"Finding Nemo Submarine Voyage","rarity":"uncommon","id":"finding-nemo-submarine-voyage","subtitle":"Dark Rides & Classic Attractions","details":"Yellow submarines dive past lava, a sunken ship and Nemo's friends through projected reef scenes in this Disneyland voyage, reopened in 2007.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Finding%20Nemo%20Submarine%20Voyage%20%2828099369910%29.jpg?width=1024"},{"name":"Race Through New York Starring Jimmy Fallon","rarity":"uncommon","id":"race-through-new-york-starring-jimmy-fallon","subtitle":"Dark Rides & Classic Attractions","details":"A flying theatre races Jimmy Fallon through New York landmarks and to the moon in this simulator, opened at Universal Studios Florida in 2017.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Race%20Through%20New%20York%20Starring%20Jimmy%20Fallon%20%2836916486110%29.jpg?width=1024"},{"name":"The Cat in the Hat","rarity":"uncommon","id":"the-cat-in-the-hat","subtitle":"Dark Rides & Classic Attractions","details":"Spinning couches tumble through a rainy-day house of chaos with Thing One and Thing Two in this Seuss Landing dark ride, opened in 1999.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CatInTheHatEnt.JPG?width=1024"},{"name":"One Fish, Two Fish, Red Fish, Blue Fish","rarity":"uncommon","id":"one-fish-two-fish-red-fish-blue-fish","subtitle":"Dark Rides & Classic Attractions","details":"Flying fish spin and dodge squirting water statues to Dr. Seuss rhymes on this aerial carousel at Universal Islands of Adventure, opened in 1999.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/OneFishTwoFishRedFishBlueFishEntrance.JPG?width=1024"},{"name":"Kang & Kodos' Twirl 'n' Hurl","rarity":"uncommon","id":"kang-and-kodos-twirl-n-hurl","subtitle":"Dark Rides & Classic Attractions","details":"Flying saucers piloted by Simpsons aliens spin riders to zap Springfield targets on this aerial ride at Universal Studios Florida, opened in 2013.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kang%20%26%20Kodos%27%20Twirl%20%27n%27%20Hurl%20May%202023.JPG?width=1024"},{"name":"Doctor Doom's Fearfall","rarity":"uncommon","id":"doctor-dooms-fearfall","subtitle":"Dark Rides & Classic Attractions","details":"Twin towers launch riders 150 feet up then drop them over Marvel Super Hero Island in this space-shot drop tower at Islands of Adventure, opened in 1999.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FearFallExt.JPG?width=1024"},{"name":"The High in the Sky Seuss Trolley Train Ride","rarity":"uncommon","id":"the-high-in-the-sky-seuss-trolley-train-ride","subtitle":"Dark Rides & Classic Attractions","details":"Slow elevated trolleys loop above Seuss Landing telling stories of the Sneetches and a Seuss alphabet on this train ride, opened in 2006.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TheHighInTheSkySeussTrolleyTrainRide.JPG?width=1024"},{"name":"Hogwarts Express","rarity":"uncommon","id":"hogwarts-express","subtitle":"Dark Rides & Classic Attractions","details":"A real train journey between King's Cross and Hogsmeade, with different window scenes each direction, linking Universal's two Florida parks since 2014.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hogwarts%20Express%20%2823041906913%29.jpg?width=1024"},{"name":"WEB SLINGERS: A Spider-Man Adventure","rarity":"uncommon","id":"web-slingers-a-spider-man-adventure","subtitle":"Dark Rides & Classic Attractions","details":"Riders sling virtual webs by hand to catch runaway Spider-Bots in this interactive dark ride, opened in Avengers Campus at California Adventure in 2021.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Disney%20California%20Adventure%20%2851242306845%29.jpg?width=1024"},{"name":"Monsters, Inc. Mike & Sulley to the Rescue!","rarity":"uncommon","id":"monsters-inc-mike-and-sulley-to-the-rescue","subtitle":"Dark Rides & Classic Attractions","details":"Taxi cabs race through Monstropolis hiding Boo from Randall and the Child Detection Agency in this California Adventure dark ride, opened in 2006.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monsters%2C%20Inc.%20Mike%20%26%20Sulley%20to%20the%20Rescue%21%2004.jpg?width=1024"},{"name":"Dumbo the Flying Elephant","rarity":"uncommon","id":"dumbo-the-flying-elephant","subtitle":"Dark Rides & Classic Attractions","details":"The flying elephant from Disney's 1941 film spins riders who control their own height, an opening-day Disneyland flat ride from 1955 copied at parks worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dumbo%20the%20Flying%20Elephant%20%2829331972100%29.jpg?width=1024"},{"name":"Mad Tea Party","rarity":"uncommon","id":"mad-tea-party","subtitle":"Dark Rides & Classic Attractions","details":"Giant teacups spin on three turntables under lanterns in this Alice in Wonderland flat ride, an opening-day Disneyland attraction from 1955.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mad%20Teacup%20Ride%20in%20action%20-%20panoramio.jpg?width=1024"},{"name":"King Arthur Carrousel","rarity":"uncommon","id":"king-arthur-carrousel","subtitle":"Dark Rides & Classic Attractions","details":"Hand-carved horses gallop around a 1922 Dentzel carousel moved to Disneyland for opening day in 1955, named for King Arthur and Lancelot's horse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/King%20Arthur%27s%20Carrousel.JPG?width=800"},{"name":"Pinocchio's Daring Journey","rarity":"common","id":"pinocchios-daring-journey","subtitle":"Dark Rides & Classic Attractions","details":"Wooden cars follow Pinocchio from Stromboli's theatre to Pleasure Island and Monstro in this Disneyland dark ride, opened in 1983.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pinocchio%27s%20Daring%20Journey.jpg?width=1024"},{"name":"Fast & Furious: Supercharged","rarity":"common","id":"fast-and-furious-supercharged","subtitle":"Dark Rides & Classic Attractions","details":"A party bus tour dives into a high-speed chase with Dom Toretto's crew in this screen-based ride, opened at Universal Studios Florida in 2018.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fast%20%26%20Furious%20Supercharged%20%28Universal%20Studios%20Florida%29%201.jpg?width=1024"},{"name":"Storm Force Accelatron","rarity":"common","id":"storm-force-accelatron","subtitle":"Dark Rides & Classic Attractions","details":"Spinning cars whirl to help Storm defeat Magneto in this teacup-style Marvel flat ride at Universal Islands of Adventure, opened in 2000.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StormForce.JPG?width=1024"},{"name":"Astro Orbiter","rarity":"common","id":"astro-orbiter","subtitle":"Dark Rides & Classic Attractions","details":"Rocket ships circle high above Tomorrowland on this aerial carousel, giving riders a pilot's view over the Magic Kingdom hub since 1974 in earlier form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Astro%20Orbiter%20%2828581637303%29.jpg?width=1024"},{"name":"The Magic Carpets of Aladdin","rarity":"common","id":"the-magic-carpets-of-aladdin","subtitle":"Dark Rides & Classic Attractions","details":"Flying carpets tilt and bob around a giant genie lamp while a camel spits at riders in this Adventureland spinner, opened at Magic Kingdom in 2001.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US%20Magic%20Kingdom%201211%20%2871%29%20%2817223326646%29.jpg?width=1024"},{"name":"Disneyland Railroad","rarity":"common","id":"disneyland-railroad","subtitle":"Dark Rides & Classic Attractions","details":"Steam trains circle Walt's park, passing a Grand Canyon diorama and primeval dinosaurs, a railroad Walt built into Disneyland from opening day in 1955.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Disneyland%20Railroad%20Station%2002.jpg?width=1024"},{"name":"Walt Disney World Railroad","rarity":"common","id":"walt-disney-world-railroad","subtitle":"Dark Rides & Classic Attractions","details":"Authentic steam locomotives circle Magic Kingdom with stops in Frontierland and Fantasyland on this grand-circle railroad, opened in 1971.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Walt%20Disney%20World%20Railroad%20Main%20Street%20USA%20Station%2001.jpg?width=1024"},{"name":"Mark Twain Riverboat","rarity":"common","id":"mark-twain-riverboat","subtitle":"Dark Rides & Classic Attractions","details":"A white stern-wheeler paddles around the Rivers of America past frontier settlements in this Disneyland riverboat, named for Samuel Clemens, opened in 1955.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mark%20Twain%20Riverboat%2C%20Disneyland.jpg?width=1024"},{"name":"Liberty Belle Riverboat","rarity":"common","id":"liberty-belle-riverboat","subtitle":"Dark Rides & Classic Attractions","details":"A working steam paddle-wheeler cruises the Rivers of America at Magic Kingdom, built as the Liberty Belle and sailing Liberty Square since 1973 in earlier name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Liberty%20Belle%20Riverboat%20by%20hyku.jpg?width=1024"},{"name":"Walt Disney World Monorail","rarity":"common","id":"walt-disney-world-monorail","subtitle":"Dark Rides & Classic Attractions","details":"Beam-riding monorails loop the Seven Seas Lagoon and glide straight through the Contemporary Resort on this iconic transport system, opened in 1971.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WDW%20Monorail%202006.jpg?width=1024"},{"name":"Casey Jr. Circus Train","rarity":"common","id":"casey-jr-circus-train","subtitle":"Dark Rides & Classic Attractions","details":"A miniature circus train chugs over Storybook Land hills in this gentle Disneyland ride, named for the little engine from Dumbo and opened in 1955.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Casey%20Jr.%20Circus%20Train.jpg?width=1024"},{"name":"Storybook Land Canal Boats","rarity":"common","id":"storybook-land-canal-boats","subtitle":"Dark Rides & Classic Attractions","details":"Small boats sail through miniature villages from Disney fairy tales, entering through the open mouth of Monstro the Whale at Disneyland since 1955.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Disneyland-Storybookland-1.jpg?width=1024"},{"name":"Autopia","rarity":"common","id":"autopia","subtitle":"Dark Rides & Classic Attractions","details":"Miniature cars let young drivers steer their own roadway through Tomorrowland on this guided driving ride, an opening-day Disneyland attraction from 1955.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Autopia.jpg?width=1024"},{"name":"Tomorrowland Speedway","rarity":"common","id":"tomorrowland-speedway","subtitle":"Dark Rides & Classic Attractions","details":"Gas-powered race cars follow a guide rail around a four-lane track at Magic Kingdom, letting children drive at a gentle seven miles per hour since 1971.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-SPEEDWAY-MAGIC%20KINGDOM-WALT%20DISNEY%20WORLD%20-%20panoramio.jpg?width=1024"}]});
